toolScript:
let db = null;
        const dropZone = document.getElementById('drop-zone');
        const fileInput = document.getElementById('db-file');
        dropZone.onclick = () => fileInput.click();
        fileInput.onchange = (e) => handleFile(e.target.files[0]);
        async function handleFile(file) {
            if (!file) return;
            const config = { locateFile: filename => `https://cdnjs.cloudflare.com/ajax/libs/sql.js/1.8.0/sql-wasm.wasm` };
            try {
                const SQL = await initSqlJs(config);
                const reader = new FileReader();
                reader.onload = function () {
                    const Uints = new Uint8Array(reader.result);
                    db = new SQL.Database(Uints);
                    document.getElementById('drop-zone').classList.add('hidden');
                    document.getElementById('db-interface').classList.remove('hidden');
                    executeSQL(); // Run initial listing query
                };
                reader.readAsArrayBuffer(file);
            } catch (err) {
                alert("Critical Initialization Error: WASM binary could not be mapped. Check your network connection for the CDN load.");
            }
        }
        function executeSQL() {
            if (!db) return;
            const sql = document.getElementById('query-editor').value;
            const table = document.getElementById('result-table');
            const section = document.getElementById('results-section');
            const rowCountEl = document.getElementById('row-count');
            try {
                const results = db.exec(sql);
                table.innerHTML = "";
                section.classList.remove('hidden');
                if (results.length === 0) {
                    table.innerHTML = "<tr><td class='p-8 text-slate-400 italic text-center uppercase tracking-widest'>Query processed. Result set is empty.</td></tr>";
                    rowCountEl.innerText = "0 Rows Returned";
                    return;
                }
                const columns = results[0].columns;
                const values = results[0].values;
                rowCountEl.innerText = `${values.length.toLocaleString()} Rows Returned`;
                // Header
                let head = "<thead><tr class='bg-slate-900 text-white uppercase text-[10px] tracking-widest'>";
                columns.forEach(col => head += `<th class="p-3 font-bold">${col}</th>`);
                head += "</tr></thead><tbody>";
                // Body
                values.forEach((row, rowIndex) => {
                    head += `<tr class='border-b border-slate-100 hover:bg-blue-50 transition-colors ${rowIndex % 2 === 0 ? "bg-white" : "bg-slate-50/30"}'>`;
                    row.forEach(val => {
                        const displayVal = val === null ? '<span class="text-slate-300 italic">NULL</span>' : val;
                        head += `<td class="p-3 truncate max-w-xs text-xs font-mono text-slate-600">${displayVal}</td>`;
                    });
                    head += "</tr>";
                });
                head += "</tbody>";
                table.innerHTML = head;
            } catch (err) {
                table.innerHTML = `<tr><td class="p-8 text-red-500 font-bold text-center bg-red-50 rounded-2xl border-2 border-red-100">
                    <div class="uppercase tracking-widest mb-2 text-xs">Syntax Error Detected</div>
                    ${err.message}
                </td></tr>`;
                section.classList.remove('hidden');
                rowCountEl.innerText = "Execution Failed";
            }
        }
        function resetEditor() {
            if (!confirm("Purge current terminal session?")) return;
            document.getElementById('query-editor').value = "";
        }
        // --- SCROLL LOGIC ---
